'use client'

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from 'react'
import { HugeiconsIcon } from '@hugeicons/react'
import {
  BookOpen01Icon,
  LibraryIcon,
  PencilEdit02Icon,
  Search01Icon,
  SidebarLeftIcon,
} from '@hugeicons/core-free-icons'
import {
  SIDEBAR_CLIP,
  SIDEBAR_CLIP_OPEN,
  SIDEBAR_CLIP_RAIL,
  SIDEBAR_FOCUS,
  SidebarAvatar,
  SidebarCanvas,
  SidebarCloseButton,
  SidebarIconButton,
  SidebarMain,
  SidebarMark,
  SidebarMenuButton,
  SidebarNavList,
  SidebarSheet,
  SidebarTitle,
  SidebarTopbar,
  sidebarIcon,
  type SidebarItem,
} from '@/components/blocks/sidebar/sidebar'
import { useControlledState } from '@/lib/hooks/use-controlled-state'
import { cn } from '@/lib/utils'

export type SidebarUser = { name: string; detail?: string; href: string }

const DEFAULT_ACTIONS: SidebarItem[] = [
  { id: 'new', label: 'New draft', href: '#', icon: sidebarIcon(PencilEdit02Icon) },
  { id: 'search', label: 'Search', href: '#', icon: sidebarIcon(Search01Icon) },
  { id: 'library', label: 'Library', href: '#', icon: sidebarIcon(LibraryIcon) },
  { id: 'reviews', label: 'Reviews', href: '#', icon: sidebarIcon(BookOpen01Icon) },
]

const DEFAULT_RECENTS: SidebarItem[] = [
  { id: 'release-notes', label: 'Release notes 2.4', href: '#' },
  { id: 'dialog-motion', label: 'Dialog motion pass', href: '#' },
  { id: 'focus-audit', label: 'Focus ring audit', href: '#' },
  { id: 'token-rename', label: 'Token rename plan', href: '#' },
  { id: 'tooltip-delay', label: 'Tooltip delay study', href: '#' },
  { id: 'sidebar-review', label: 'Sidebar block review', href: '#' },
]

const DEFAULT_USER: SidebarUser = { name: 'Mira Tan', detail: 'mira@nexvyn.dev', href: '#' }

const SWAP =
  'absolute inset-0 flex items-center justify-center transition-[opacity,scale,filter] duration-(--motion-dur-base) ease-(--motion-ease-in-out) motion-reduce:transition-none'

export interface SidebarCollapsibleProps extends Omit<
  ComponentPropsWithoutRef<'div'>,
  'title' | 'defaultValue' | 'onChange'
> {
  actions?: SidebarItem[]
  recents?: SidebarItem[]
  recentsLabel?: string
  user?: SidebarUser
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  brand?: string
  brandHref?: string
  title?: ReactNode
  sidebarLabel?: string
  navLabel?: string
  expandLabel?: string
  collapseLabel?: string
  menuLabel?: string
  closeLabel?: string
  children?: ReactNode
}

export const SidebarCollapsible = forwardRef<HTMLDivElement, SidebarCollapsibleProps>(
  (
    {
      actions = DEFAULT_ACTIONS,
      recents = DEFAULT_RECENTS,
      recentsLabel = 'Recent',
      user = DEFAULT_USER,
      value,
      defaultValue = 'release-notes',
      onValueChange,
      open,
      defaultOpen = true,
      onOpenChange,
      brand = 'Nexvyn',
      brandHref = '#',
      title,
      sidebarLabel = 'Sidebar',
      navLabel = 'Main',
      expandLabel = 'Expand sidebar',
      collapseLabel = 'Collapse sidebar',
      menuLabel = 'Open navigation',
      closeLabel = 'Close navigation',
      children,
      className,
      ...props
    },
    ref,
  ) => {
    const id = useId()
    const asideId = `${id}-aside`
    const sheetId = `${id}-sheet`
    const triggerRef = useRef<HTMLButtonElement>(null)
    const expandRef = useRef<HTMLButtonElement>(null)
    const collapseRef = useRef<HTMLButtonElement>(null)
    const moveFocus = useRef(false)
    const [sheetOpen, setSheetOpen] = useState(false)
    const [expanded, setExpanded] = useControlledState(open, defaultOpen, onOpenChange)
    const [active, setActive] = useControlledState(value, defaultValue, onValueChange)
    const activeLabel = [...actions, ...recents].find((item) => item.id === active)?.label

    useEffect(() => {
      if (!moveFocus.current) return
      moveFocus.current = false
      ;(expanded ? collapseRef : expandRef).current?.focus()
    }, [expanded])

    const toggle = () => {
      moveFocus.current = true
      setExpanded(!expanded)
    }

    const brandLink = (hidden: boolean) => (
      <a
        href={brandHref}
        inert={hidden}
        className={cn(
          'flex h-10 items-center gap-2 rounded-md px-1.5 text-sm text-(--color-fg)',
          SIDEBAR_FOCUS,
        )}
      >
        <SidebarMark />
        <span
          className={cn(
            'transition-opacity duration-(--motion-dur-fast) ease motion-reduce:transition-none',
            hidden && 'opacity-0',
          )}
        >
          {brand}
        </span>
      </a>
    )

    const panel = (inSheet: boolean) => {
      const compact = !inSheet && !expanded
      const select = (next: string) => {
        setActive(next)
        if (inSheet) setSheetOpen(false)
      }

      return (
        <>
          <div className="relative flex h-14 shrink-0 items-center gap-1 px-2">
            {brandLink(compact)}
            {inSheet ? (
              <SidebarCloseButton label={closeLabel} onClose={() => setSheetOpen(false)} />
            ) : (
              <>
                <button
                  ref={expandRef}
                  type="button"
                  aria-label={expandLabel}
                  aria-expanded={false}
                  aria-controls={asideId}
                  inert={!compact}
                  onClick={toggle}
                  className={cn(
                    'group/expand absolute start-2 top-2 flex size-10 items-center justify-center rounded-md',
                    SIDEBAR_FOCUS,
                    !compact && 'invisible',
                  )}
                >
                  <span aria-hidden="true" className="relative size-7">
                    <span
                      className={cn(
                        SWAP,
                        'group-hover/expand:scale-90 group-hover/expand:opacity-0 group-hover/expand:blur-[2px] group-focus-visible/expand:scale-90 group-focus-visible/expand:opacity-0 group-focus-visible/expand:blur-[2px]',
                      )}
                    >
                      <SidebarMark />
                    </span>
                    <span
                      className={cn(
                        SWAP,
                        'scale-90 text-(--color-fg) opacity-0 blur-[2px] group-hover/expand:scale-100 group-hover/expand:opacity-100 group-hover/expand:blur-none group-focus-visible/expand:scale-100 group-focus-visible/expand:opacity-100 group-focus-visible/expand:blur-none',
                      )}
                    >
                      <HugeiconsIcon
                        icon={SidebarLeftIcon}
                        size={18}
                        strokeWidth={1.5}
                        className="rtl:-scale-x-100"
                      />
                    </span>
                  </span>
                </button>
                <SidebarIconButton
                  ref={collapseRef}
                  label={collapseLabel}
                  aria-expanded={true}
                  aria-controls={asideId}
                  inert={compact}
                  onClick={toggle}
                  className="ms-auto"
                >
                  <HugeiconsIcon
                    icon={SidebarLeftIcon}
                    size={18}
                    strokeWidth={1.5}
                    className="rtl:-scale-x-100"
                  />
                </SidebarIconButton>
              </>
            )}
          </div>
          <nav aria-label={navLabel} className="flex min-h-0 flex-1 flex-col">
            <div className="flex min-h-0 flex-1 flex-col overflow-y-auto px-2 pb-3">
              <SidebarNavList
                items={actions}
                activeId={active}
                compact={compact}
                onSelect={select}
              />
              <div
                inert={compact}
                className={cn(
                  'transition-opacity duration-(--motion-dur-base) ease-(--motion-ease-in-out) motion-reduce:transition-none',
                  compact && 'opacity-0',
                )}
              >
                <SidebarNavList
                  label={recentsLabel}
                  items={recents}
                  activeId={active}
                  onSelect={select}
                />
              </div>
            </div>
          </nav>
          <div className="border-t border-(--color-border) p-2">
            <a
              href={user.href}
              className={cn(
                'flex h-11 items-center gap-3 rounded-md p-1 transition-colors duration-(--motion-dur-fast) ease hover:bg-(--color-fg)/4 motion-reduce:transition-none',
                SIDEBAR_FOCUS,
                compact ? 'w-10' : 'w-full',
              )}
            >
              <SidebarAvatar name={user.name} />
              <span className={cn('flex min-w-0 flex-col', compact && 'sr-only')}>
                <span className="truncate text-sm text-(--color-fg)">{user.name}</span>
                {user.detail && (
                  <span className="truncate text-xs text-(--color-muted)">{user.detail}</span>
                )}
              </span>
            </a>
          </div>
        </>
      )
    }

    return (
      <div
        ref={ref}
        className={cn(
          'relative flex h-full min-h-0 w-full overflow-hidden bg-(--color-bg)',
          className,
        )}
        {...props}
      >
        <div
          aria-hidden="true"
          className={cn('hidden shrink-0 md:block', expanded ? 'w-64' : 'w-14')}
        />
        <aside
          id={asideId}
          aria-label={sidebarLabel}
          className={cn(
            'absolute inset-y-0 start-0 z-1 hidden w-64 flex-col bg-(--color-surface) md:flex',
            SIDEBAR_CLIP,
            expanded ? SIDEBAR_CLIP_OPEN : SIDEBAR_CLIP_RAIL,
          )}
        >
          {panel(false)}
        </aside>
        <SidebarMain className="md:border-s md:border-(--color-border)">
          <SidebarTopbar className="border-b-0 sm:px-6">
            <SidebarMenuButton
              ref={triggerRef}
              open={sheetOpen}
              controls={sheetId}
              label={menuLabel}
              onOpen={() => setSheetOpen(true)}
            />
            <SidebarTitle>{title ?? activeLabel}</SidebarTitle>
          </SidebarTopbar>
          {children ?? <SidebarCanvas />}
        </SidebarMain>
        <SidebarSheet
          id={sheetId}
          open={sheetOpen}
          onOpenChange={setSheetOpen}
          triggerRef={triggerRef}
          label={sidebarLabel}
        >
          {panel(true)}
        </SidebarSheet>
      </div>
    )
  },
)
SidebarCollapsible.displayName = 'SidebarCollapsible'

'use client'

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  type ComponentPropsWithoutRef,
  type ReactNode,
  type RefObject,
} from 'react'
import { motion, useReducedMotion } from 'motion/react'
import { HugeiconsIcon } from '@hugeicons/react'
import { Cancel01Icon, Menu01Icon } from '@hugeicons/core-free-icons'
import { useFocusTrap } from '@/lib/hooks/use-focus-trap'
import { cn } from '@/lib/utils'

export type SidebarIconGlyph = typeof Menu01Icon
export type SidebarItem = { id: string; label: string; href: string; icon?: ReactNode }
export type SidebarGroup = { id: string; label?: string; items: SidebarItem[] }

export function sidebarIcon(icon: SidebarIconGlyph) {
  return <HugeiconsIcon icon={icon} size={18} strokeWidth={1.5} />
}

export const SIDEBAR_FOCUS =
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent)'

const ROW = 'h-9 [@media(hover:none)]:h-11'

// Matches --motion-dur-base and --motion-ease-in-out, so the page moves with the panel.
const SHIFT = { duration: 0.2, ease: [0.65, 0, 0.35, 1] as const }

export const SIDEBAR_CLIP =
  'transition-[clip-path] duration-(--motion-dur-base) ease-(--motion-ease-in-out) motion-reduce:transition-none'

export const SIDEBAR_CLIP_RAIL =
  '[clip-path:inset(0_calc(100%_-_3.5rem)_0_0)] rtl:[clip-path:inset(0_0_0_calc(100%_-_3.5rem))]'

export const SIDEBAR_CLIP_OPEN = '[clip-path:inset(0_0_0_0)]'

export interface SidebarLinkProps extends Omit<ComponentPropsWithoutRef<'a'>, 'children' | 'href'> {
  item: SidebarItem
  active?: boolean
  compact?: boolean
}

export const SidebarLink = forwardRef<HTMLAnchorElement, SidebarLinkProps>(
  ({ item, active, compact, onClick, className, ...props }, ref) => (
    <a
      ref={ref}
      href={item.href}
      aria-current={active ? 'page' : undefined}
      onClick={(event) => {
        onClick?.(event)
        if (item.href === '#') event.preventDefault()
      }}
      className={cn(
        'flex items-center gap-3 rounded-md px-2.5 text-sm transition-colors duration-(--motion-dur-fast) ease motion-reduce:transition-none',
        ROW,
        SIDEBAR_FOCUS,
        compact ? 'w-10' : 'w-full',
        active
          ? 'bg-(--color-fg)/8 text-(--color-fg)'
          : 'text-(--color-muted) hover:bg-(--color-fg)/4 hover:text-(--color-fg)',
        className,
      )}
      {...props}
    >
      {item.icon && (
        <span
          aria-hidden="true"
          className={cn(
            'flex size-5 shrink-0 items-center justify-center',
            active ? 'text-(--color-fg)' : 'opacity-80',
          )}
        >
          {item.icon}
        </span>
      )}
      <span className={compact ? 'sr-only' : 'truncate'}>{item.label}</span>
    </a>
  ),
)
SidebarLink.displayName = 'SidebarLink'

export interface SidebarNavListProps {
  label?: string
  items: SidebarItem[]
  activeId?: string
  compact?: boolean
  onSelect?: (id: string) => void
  className?: string
}

export function SidebarNavList({
  label,
  items,
  activeId,
  compact,
  onSelect,
  className,
}: SidebarNavListProps) {
  const headingId = useId()

  return (
    <div className={cn('flex flex-col gap-1', className)}>
      {label && (
        <h2 id={headingId} className="truncate px-2.5 pt-4 pb-1 text-xs text-(--color-muted)">
          {label}
        </h2>
      )}
      <ul aria-labelledby={label ? headingId : undefined} className="flex flex-col gap-0.5">
        {items.map((item) => (
          <li key={item.id}>
            <SidebarLink
              item={item}
              active={item.id === activeId}
              compact={compact}
              onClick={() => onSelect?.(item.id)}
            />
          </li>
        ))}
      </ul>
    </div>
  )
}

export interface SidebarIconButtonProps extends ComponentPropsWithoutRef<'button'> {
  label: string
}

export const SidebarIconButton = forwardRef<HTMLButtonElement, SidebarIconButtonProps>(
  ({ label, className, children, ...props }, ref) => (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      className={cn(
        'flex size-10 shrink-0 items-center justify-center rounded-md text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:bg-(--color-fg)/4 hover:text-(--color-fg) motion-reduce:transition-none [@media(hover:none)]:size-11',
        SIDEBAR_FOCUS,
        className,
      )}
      {...props}
    >
      <span aria-hidden="true" className="inline-flex">
        {children}
      </span>
    </button>
  ),
)
SidebarIconButton.displayName = 'SidebarIconButton'

export function SidebarMark({ letter = 'N', className }: { letter?: string; className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        'flex size-7 shrink-0 items-center justify-center rounded-md bg-(--color-fg) text-xs text-(--color-bg)',
        className,
      )}
    >
      {letter}
    </span>
  )
}

export function SidebarAvatar({ name, className }: { name: string; className?: string }) {
  const initials = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  return (
    <span
      aria-hidden="true"
      className={cn(
        'squircle flex size-8 shrink-0 items-center justify-center bg-(--color-fg)/8 text-xs text-(--color-fg)',
        className,
      )}
    >
      {initials}
    </span>
  )
}

export function SidebarTopbar({
  className,
  children,
}: {
  className?: string
  children: ReactNode
}) {
  return (
    <div
      className={cn(
        'flex h-14 shrink-0 items-center gap-1 border-b border-(--color-border) px-2 sm:px-4',
        className,
      )}
    >
      {children}
    </div>
  )
}

export function SidebarTitle({ children }: { children: ReactNode }) {
  return <h1 className="min-w-0 truncate px-2 text-sm text-(--color-fg)">{children}</h1>
}

export function SidebarMain({ className, children }: { className?: string; children: ReactNode }) {
  const reduceMotion = useReducedMotion()

  return (
    <motion.div
      layout={reduceMotion ? false : 'position'}
      transition={{ layout: SHIFT }}
      className={cn('flex min-w-0 flex-1 flex-col overflow-y-auto', className)}
    >
      {children}
    </motion.div>
  )
}

const FILL = 'rounded-md bg-(--color-fg)/7'

export function SidebarCanvas() {
  return (
    <div aria-hidden="true" className="flex flex-col gap-6 px-4 py-6 sm:px-8">
      <div className="flex flex-col gap-3">
        <span className={cn(FILL, 'h-5 w-40')} />
        <span className={cn(FILL, 'h-2.5 w-64 max-w-full')} />
      </div>
      <div className="grid gap-3 sm:grid-cols-3">
        {[0, 1, 2].map((index) => (
          <div key={index} className="flex flex-col gap-3 rounded-md bg-(--color-fg)/4 p-4">
            <span className={cn(FILL, 'h-2 w-16')} />
            <span className={cn(FILL, 'h-5 w-24')} />
          </div>
        ))}
      </div>
      <span className={cn(FILL, 'block h-48')} />
      <div className="flex flex-col gap-2">
        {[0, 1, 2, 3].map((index) => (
          <div key={index} className="flex items-center gap-3 rounded-md bg-(--color-fg)/4 p-3">
            <span className="squircle size-8 shrink-0 bg-(--color-fg)/7" />
            <span className={cn(FILL, 'h-2.5 w-40 max-w-[50%]')} />
            <span className={cn(FILL, 'ms-auto h-2.5 w-12')} />
          </div>
        ))}
      </div>
    </div>
  )
}

export interface SidebarMenuButtonProps {
  open: boolean
  controls: string
  label: string
  onOpen: () => void
}

export const SidebarMenuButton = forwardRef<HTMLButtonElement, SidebarMenuButtonProps>(
  ({ open, controls, label, onOpen }, ref) => (
    <SidebarIconButton
      ref={ref}
      label={label}
      aria-expanded={open}
      aria-controls={controls}
      aria-haspopup="dialog"
      onClick={onOpen}
      className="md:hidden"
    >
      {sidebarIcon(Menu01Icon)}
    </SidebarIconButton>
  ),
)
SidebarMenuButton.displayName = 'SidebarMenuButton'

export function SidebarCloseButton({ label, onClose }: { label: string; onClose: () => void }) {
  return (
    <SidebarIconButton label={label} onClick={onClose} className="ms-auto">
      {sidebarIcon(Cancel01Icon)}
    </SidebarIconButton>
  )
}

export interface SidebarSheetProps {
  id: string
  open: boolean
  onOpenChange: (open: boolean) => void
  triggerRef: RefObject<HTMLElement | null>
  label: string
  children: ReactNode
}

export function SidebarSheet({
  id,
  open,
  onOpenChange,
  triggerRef,
  label,
  children,
}: SidebarSheetProps) {
  const panelRef = useRef<HTMLDivElement>(null)
  const onOpenChangeRef = useRef(onOpenChange)

  useEffect(() => {
    onOpenChangeRef.current = onOpenChange
  })

  useFocusTrap(panelRef, open, triggerRef)

  useEffect(() => {
    if (!open) return
    const close = () => onOpenChangeRef.current(false)
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return
      event.preventDefault()
      close()
    }
    const desktop = window.matchMedia('(min-width: 48rem)')
    const handleDesktop = (event: MediaQueryListEvent) => {
      if (event.matches) close()
    }
    document.addEventListener('keydown', handleKeyDown)
    desktop.addEventListener('change', handleDesktop)
    return () => {
      document.removeEventListener('keydown', handleKeyDown)
      desktop.removeEventListener('change', handleDesktop)
    }
  }, [open])

  return (
    <div
      inert={!open}
      className={cn('absolute inset-0 z-10 md:hidden', !open && 'pointer-events-none')}
    >
      <button
        type="button"
        tabIndex={-1}
        aria-hidden="true"
        onClick={() => onOpenChange(false)}
        className={cn(
          'absolute inset-0 cursor-default bg-(--color-bg)/70 transition-opacity ease-(--motion-ease-out) motion-reduce:transition-none',
          open
            ? 'opacity-100 duration-(--motion-dur-base)'
            : 'opacity-0 duration-(--motion-dur-fast)',
        )}
      />
      <div
        ref={panelRef}
        id={id}
        role="dialog"
        aria-modal="true"
        aria-label={label}
        className={cn(
          'absolute inset-y-0 start-0 flex w-72 max-w-[85%] flex-col border-e border-(--color-border) bg-(--color-surface) transition-[translate] ease-(--motion-ease-out) motion-reduce:transition-none',
          open
            ? 'translate-x-0 duration-(--motion-dur-base)'
            : '-translate-x-full duration-(--motion-dur-fast) rtl:translate-x-full',
        )}
      >
        {children}
      </div>
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'

export function useControlledState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
): [T, (next: T) => void] {
  const [inner, setInner] = useState(defaultValue)
  const isControlled = value !== undefined
  const current = isControlled ? value : inner
  const onChangeRef = useRef(onChange)

  useEffect(() => {
    onChangeRef.current = onChange
  })

  const set = useCallback(
    (next: T) => {
      if (!isControlled) setInner(next)
      onChangeRef.current?.(next)
    },
    [isControlled],
  )

  return [current, set]
}

'use client'

import { useEffect, useRef, type RefObject } from 'react'

export function useFocusTrap(
  containerRef: RefObject<HTMLElement | null>,
  active: boolean,
  restoreRef?: RefObject<HTMLElement | null>,
) {
  const previouslyFocusedRef = useRef<HTMLElement | null>(null)

  useEffect(() => {
    if (!active) return

    previouslyFocusedRef.current = document.activeElement as HTMLElement | null
    const restoreTarget = restoreRef?.current ?? previouslyFocusedRef.current

    const container = containerRef.current
    if (!container) return

    const focusable = container.querySelectorAll<HTMLElement>(
      'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])',
    )
    if (focusable.length) {
      ;(focusable[0] as HTMLElement).focus()
    }

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return

      const focusableEls = container.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])',
      )
      if (!focusableEls.length) return

      const first = focusableEls[0] as HTMLElement
      const last = focusableEls[focusableEls.length - 1] as HTMLElement

      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault()
          last.focus()
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault()
          first.focus()
        }
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => {
      document.removeEventListener('keydown', handleKeyDown)
      if (restoreTarget && typeof restoreTarget.focus === 'function') {
        restoreTarget.focus()
      }
    }
  }, [active, containerRef, restoreRef])
}
